INSERT INTO "crosses_cross" VALUES(1,'Apex Oceanic Sovereign','apex-oceanic-sovereign','Mega Cruise Liner','Apex Oceanic Sovereign is a flagship mega liner engineered for supreme Atlantic comfort. Features expansive multi-deck atriums, infinity wake pools, Michelin-inspired dining, and Broadway-grade celestial entertainment.','New York Harbor, USA','742 Zenith Boulevard, Downtown Metro',250000,3200,'','/static/images/vessels/apex_oceanic_sovereign.jpg','Helipad, Infinity Wake Pool, Royal Casino, 12 Gourmet Restaurants, Thalassotherapy Spa, Broadway Theatre, Sky Lounge','Non-marking athletic footwear required. No glassware inside the arena perimeter.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.896712','2026-10-04 06:42:05.491142',2,16,'Manhattan Cruise Terminal, Pier 88','Bermuda & Atlantic Crossing','The Grand Sovereign Dining Salon, Le Cirque Coastal Grill, Prime 1855 Steakhouse, Horizon Gelato Bar',8,'Broadway Cast Musical Revues, Midnight Jazz Cellar, Casino Royale, Open-Air Starlight Cinema','Day 1: Sailaway from Manhattan with skyline champagne salute
INSERT INTO "crosses_cross" VALUES(2,'Heritage Star Clipper','heritage-star-clipper','Luxury Ocean Cruise','Heritage Star Clipper combines classical nautical grace with modern presidential luxury. Sail through secluded Caribbean harbors with teak decks, polished brass, and personalized butler stateroom hospitality.','Bridgetown, Barbados','124 Heritage Way, North Oakridge',120000,320,'','/static/images/vessels/heritage_star_clipper.jpg','Panoramic Teak Promenade, Sea Breeze Spa, Sunset Observation Terrace, Library Lounge, Open Bridge Access','Clean up all food and trash before departing. Sound levels restricted after 10:00 PM.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.905449','2026-10-02 09:59:19.079149',2,6,'Port of Bridgetown, Barbados','Caribbean Windward Isles','Windward Grand Salon, Teak Deck Grill, Clipper Rum & Wine Bar',7,'Live Acoustic Calypso Duo, Stargazing Deck Lectures, Nautical Master Storytelling','Day 1: Embarkation in Bridgetown & Captain’s Rum Punch Gala
INSERT INTO "crosses_cross" VALUES(3,'Aegean Pulse Yacht','aegean-pulse-yacht','Private Charter Yacht','A high-speed luxury superyacht tailored for private island hopping across the Aegean. Equipped with private jet skis, teak swim platform, private sommelier, and secluded cove anchoring capabilities.','Mykonos, Greece','89 Riverbed Industrial Park, Unit 4',45000,50,'','/static/images/vessels/aegean_pulse_yacht.jpg','Hydraulic Swim Platform, SeaBobs & Jet Skis, Jacuzzi Sun Deck, Private Chef Service, Cocktails Lounge','Wipe down equipment after sessions. Return all weights to racks.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.913536','2026-10-02 09:59:19.072662',2,4,'Tourlos New Port, Mykonos','Cyclades & Greek Islands','Mediterranean Seafood Terrace, Ouzo & Caviar Sunset Bar',5,'Sunset DJ Deck Sessions, Private Scuba Excursions','Day 1: Boarding in Mykonos & Sunset Champagne Sailaway
INSERT INTO "crosses_cross" VALUES(4,'Skyline Grandeur Explorer','skyline-grandeur-explorer','Expedition Cruise','Engineered for eco-luxury expedition voyages. Features glass-bottom observation craft, on-board marine biologists, zodiac landing fleet, and panoramic staterooms.','Galapagos Islands, Ecuador','500 Skyline Tower, 18th Floor',75000,120,'','/static/images/vessels/skyline_grandeur.jpg','Zodiac Landing Craft, Marine Biology Laboratory, Observation Deck, Spa & Sauna, Expedition Gear Locker','Licensed caterers required for food service. Strictly no open flame decorations.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.922111','2026-10-02 09:59:19.064804',2,6,'Puerto Ayora, Santa Cruz','Galapagos Archipelago','Darwin Panoramic Bistro, Al Fresco Ocean Deck',7,'Evening Marine Biology Lectures, Starlight Astrophotography Sessions','Day 1: Embarkation at Baltra & Giant Tortoise Reserve
INSERT INTO "crosses_cross" VALUES(5,'Nordic Horizon Navigator','nordic-horizon-navigator','Expedition Cruise','Polar class luxury expedition vessel designed for arctic navigation. Boasts thermal heated outdoor infinity pools, panoramic 360-degree observation glass dome, and auroral tracking radar.','Reykjavik, Iceland','102 Innovation Drive, Suite 300',135000,480,'','/static/images/vessels/nordic_horizon.jpg','Heated Polar Infinity Pools, 360 Aurora Glass Dome, Nordic Thermal Spa, Zodiac Fleet, Helipad','No disruptive activities in common building corridors. Tech equipment must be powered off when leaving.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.930038','2026-10-04 06:42:05.512337',3,8,'Old Harbour, Reykjavik','Iceland & Arctic Circle','Nordic Fire & Ice Dining Room, Polar Aurora Tasting Cellar',8,'Northern Lights Observation Deck, Classical String Quartets','Day 1: Embarkation in Reykjavik & Geothermal Sailaway
INSERT INTO "crosses_cross" VALUES(6,'Artisan Ocean Voyager','artisan-ocean-voyager','Luxury Ocean Cruise','Artisan Ocean Voyager blends Scandinavian minimalist interior design with European culinary art. Features panoramic glass elevators, curated maritime art galleries, and expansive oceanview staterooms.','Copenhagen, Denmark','45 Bohemian Alley, Arts Quarter',165000,850,'','/static/images/vessels/artisan_ocean_voyager.jpg','Curated Marine Art Gallery, Hydrotherapy Thermal Pool, 8 Specialty Bistros, Panoramic Glass Elevators','Do not hammer nails directly into plaster without gallery approval. Maintain artwork safety distances.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.937915','2026-10-04 06:42:05.521348',3,10,'Oceankaj, Copenhagen','Baltic Capitals & Scandi Seas','Nordic Haven Restaurant, Aquavit Raw Bar, Baltic Cafe & Bakery',7,'Chamber Orchestra, Nordic Jazz Ensemble, Maritime Cinema','Day 1: Copenhagen Nyhavn sailaway
INSERT INTO "crosses_cross" VALUES(7,'Emerald Isle Seafarer','emerald-isle-seafarer','Island Hopper Cruise','Venture through mystical sea lochs, ancient castles, and Gaelic archipelagos. The vessel offers intimate boutique luxury with Celtic folk performances and regional farm-to-table seafood.','Dublin, Ireland','310 Botanical Avenue, East Greenbelt',150000,400,'','/static/images/vessels/emerald_isle_seafarer.jpg','Celtic Whiskey Tasting Lounge, Observation Deck, Gaelic Library, Wellness Suite, Heated Pool','Respect vegetation and lawn care guidelines. Quiet hours begin at 10:30 PM.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.945560','2026-10-02 09:59:19.043412',3,7,'Dublin Port, North Wall','Irish Coast & Scottish Hebrides','The Emerald Harbor Table, Gaelic Single Malt & Oyster Bar',6,'Live Celtic Traditional Music, Highland Folktale Storytelling','Day 1: Dublin departure with live traditional Celtic harpist
INSERT INTO "crosses_cross" VALUES(8,'Eastside Odyssey Catamaran','eastside-odyssey-catamaran','Private Charter Yacht','A luxury power catamaran designed for sun-soaked private charters. Features expansive front trampolines, hydraulic tender, bar lounge, and access to crystal shallow coral reefs.','Miami, Florida','78 Harbor Road, Eastside',35000,40,'','/static/images/vessels/eastside_odyssey.jpg','Foredeck Sunbathing Trampolines, Coral Reef Snorkel Gear, Wet Bar Lounge, Sound System, Tender Boat','Youth activities must have adult supervision. No hazardous materials allowed.','Free cancellation up to 24 hours prior to booking start time.',1,1,'2026-09-27 14:12:49.954147','2026-10-02 09:59:19.034912',3,3,'Miami Beach Marina, Pier B','Florida Keys & Dry Tortugas','Sunset Key Lime Grill, Tropical Cocktail Bar',4,'Bespoke Private DJ Sessions, Night Reef Snorkeling with UV lights','Day 1: Embarkation in Miami & Sunset Key Biscayne cruise
INSERT INTO "crosses_cross" VALUES(9,'MS Horizon Empress','ms-horizon-empress','Luxury Ocean Cruise','The flagship of the Cruise Hunt fleet. Featuring revolutionary architectural glass facades, panoramic sky lounges, and Michelin-inspired culinary experiences across the azure waters of the Caribbean.','Miami, Florida','Port of Miami, 1015 North America Way, Miami, FL 33132',220000,1850,'','/static/images/vessels/ms_horizon_empress.jpg','Helipad, Infinity Glass Pool, Broadway Theatre, Full-Service Ocean Spa, Casino Royale, 12 Specialty Restaurants, Star Gazing Observatory, Butler Stateroom Concierge','Formal evening attire for Captain’s Gala. Valid international passport required. Non-smoking in all staterooms and balconies.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.762538','2026-10-04 06:42:05.530190',2,18,'Port of Miami, Terminal A','Caribbean Paradise','The Grand Sovereign Dining Room, Chef''s Atelier Tasting Menu, Le Cirque French Bistro, Ocean Horizon Lido Market, Wave Bar & Grill',7,'West End Musical Production, Cirque de la Mer Acrobatic Show, Starlight Jazz Speakeasy, Ocean Cinema under the Stars','Day 1: Embarkation in Miami & Sunset Champagne Sail-Away
INSERT INTO "crosses_cross" VALUES(10,'Sovereign of the Aegean','sovereign-of-the-aegean','Luxury Ocean Cruise','Sail through classical mythology and sun-bleached coastal villages aboard a vessel designed for intimate Mediterranean grandeur and unforgettable sunsets.','Athens, Greece','Piraeus Port Terminal 2, Akti Miaouli 10, Athens, Greece',195000,1400,'','/static/images/vessels/sovereign_of_aegean.jpg','Marble Atrium, Thalassotherapy Pool, Wine Tasting Cellar, Amphitheatre, Solarium, VIP Cabana Deck, Water Sports Marina','Passport validity minimum 6 months. Casual elegant resort wear in dining venues after 6 PM.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.772283','2026-10-04 06:42:05.538891',2,15,'Port of Piraeus, Athens','Greek Isles & Mediterranean','Olympus Prime Dining, Aegean Seafood Market, Taverna Akropolis, Mediterranean Wine Terrace',6,'Greek Sirtaki Live Orchestra, Classical Strings at Sunset, Starlight Amphitheatre','Day 1: Depart Athens Historic Harbor
INSERT INTO "crosses_cross" VALUES(11,'Nordic Glacier Explorer','nordic-glacier-explorer','Expedition Cruise','An ice-strengthened luxury expedition vessel carrying naturalists and polar guides into mystical glacial fjords, thunderous waterfalls, and the Aurora Borealis.','Bergen, Norway','Skoltegrunskaien 1, 5003 Bergen, Norway',145000,650,'','/static/images/vessels/nordic_glacier.jpg','Polar Class 1A Ice Hull, Forward Observation Lounge, Heated Horizon Jacuzzis, Expedition Zodiac Boats, Science Lab, Saunas','Expedition parkas provided on board. Strict environmental wildlife proximity regulations apply.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.780532','2026-10-04 06:42:05.548012',2,10,'Bergen Cruise Port, Norway','Norwegian Fjords & Arctic','Fjord & Forest Fine Dining, Arctic Catch Seafood Bar, Aurora Observation Grill',8,'Marine Biologist Lectures, Northern Lights Stargazing, Acoustic Folk Performances','Day 1: Embarkation in Historic Bryggen, Bergen
INSERT INTO "crosses_cross" VALUES(12,'Celestia Grand Yacht','celestia-grand-yacht','Private Charter Yacht','Exclusive mega-yacht crafted for private weddings, high-society galas, corporate leadership summits, and VIP harbor charters along the Cote d’Azur.','Cote d’Azur, France','Quai Amiral Infernet, 06300 Nice, France',95000,180,'','/static/images/vessels/celestia_grand_yacht.jpg','Hydraulic Teak Swim Platform, SeaBobs, Jet Skis, Champagne Bar, Helipad, Master Penthouse Suite, Private Cinema','Barefoot or white boat shoes only on exterior teak decks. Maximum 180 guests for private charters.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.788109','2026-10-02 09:59:19.007453',3,6,'Port Lympia, Nice, France','French Riviera & Monaco','Le Riviera Private Salon, Top-Deck Caviar & Champagne Lounge, Teppanyaki at Sea',3,'Private DJ Rig, Live Saxophone Trio, Aerial Drone Video Experience','Day 1: Welcome Champagne in Nice & Twilight Cruise to Cannes
INSERT INTO "crosses_cross" VALUES(13,'Coral Odyssey Liner','coral-odyssey-liner','Island Hopper Cruise','Experience the turquoise lagoons and volcanic peaks of French Polynesia with over-lagoon balconies, Polynesian cultural masters, and pristine scuba diving.','French Polynesia','Boulevard Pomare, Papeete 98713, French Polynesia',115000,920,'','/static/images/vessels/coral_odyssey_liner.jpg','Overwater Lagoon Platform, Glass-Bottom Observation Bar, Polynesian Spa, Scuba Diving Center, Outdoor Cinema','Reef-safe sunscreen required. Lifejackets mandatory on lagoon tenders.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.795400','2026-10-04 06:42:05.559235',3,12,'Port Autonome de Papeete, Tahiti','South Pacific & Tahiti','Lagon Bleu Polynesian Gourmet, Moana Fish Grill, Vanilla Terrace',7,'Traditional Polynesian Fire Dancers, Starlight Acoustic Ukulele, Island Storytelling','Day 1: Embarkation in Papeete & Tahitian Ukulele Welcome
INSERT INTO "crosses_cross" VALUES(14,'Pacific Constellation','pacific-constellation','Mega Cruise Liner','A magnificent floating resort designed to sail right alongside calving glaciers, towering fjords, and breaching whales in Alaska’s untamed wilderness.','Seattle, Washington','2001 W Garfield St, Seattle, WA 98119',210000,2400,'','/static/images/vessels/pacific_constellation.jpg','Enclosed Glass Atrium, Glacier Viewing Promenade, Thermal Suite, Ice Skating Rink, Laser Tag, 16 Lounges','Layered cold-weather gear advised for glacier decks. Binoculars available at concierge desk.','Full refund up to 48 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-27 16:06:46.802322','2026-10-04 06:42:05.567740',3,20,'Port of Seattle, Pier 91','Alaska Glacier Bay','Great North Dining Hall, Glacier Steakhouse, Alaskan Crab Shack, Cascade Coffee Bar',7,'Broadway on Ice Spectacular, National Park Ranger Talks, Live Rock Tribute Bands','Day 1: Depart Seattle Waterfront
INSERT INTO "crosses_cross" VALUES(15,'MV Ocean Pearl','mv-ocean-pearl','Luxury Ocean Cruise','The flagship of the Arabian Sea fleet. MV Ocean Pearl features 12 sun decks, crystal glass observatory lounge, infinity swimming pool, and fine international dining. Ideal for grand weddings, executive corporate conclaves, and scheduled Mumbai-Goa voyages.','Mumbai','Terminal 1, Mumbai International Cruise Terminal, Green Gate, Mumbai, Maharashtra 400001',85000,180,'','/static/images/vessels/mv_ocean_pearl.jpg','Wi-Fi, Swimming Pool, Heliport, Fine Dining, DJ Audio Rigs, Theatre, Spa, Conference Hall, Bar Lounge','Valid government photo ID required. Mandatory safety lifeboat briefing prior to departure. Quiet hours observed after midnight.','Full refund up to 72 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-28 11:11:22.518271','2026-10-19 18:34:46.962494',2,10,'Mumbai International Cruise Terminal','Goa & Arabian Sea Coastal Route','The Captain''s Table, Konkan Spice Deck, Sapphire Panorama Lounge, Blue Lagoon Bistro',4,'Grand Ballroom, Starlight Jazz Amphitheatre, Open Deck Cinema, Ayurvedic Ocean Spa','Day 1: Sunset Welcome Cocktails & Live Sitar Ensemble
INSERT INTO "crosses_cross" VALUES(16,'Kochi Voyager Empress','kochi-voyager-empress','Scenic Coastal Cruise','Experience the emerald waterways and Arabian Sea coastline aboard the Kochi Voyager Empress. Custom built with panoramic double-glazed observation saloons and heritage wood craftsmanship.','Kochi','Ernakulam Wharf, Cochin Port Trust, Willingdon Island, Kochi, Kerala 682009',55000,120,'','/static/images/vessels/kochi_voyager_empress.jpg','Swimming Pool, Wi-Fi, Seafood Restaurant, Sun Deck, Live Music, Scuba Briefing Suite','Valid government photo ID required. Mandatory safety lifeboat briefing prior to departure. Quiet hours observed after midnight.','Full refund up to 72 hours prior to scheduled departure. Flexible date rescheduling available.',1,1,'2026-09-28 11:11:22.527891','2026-10-19 18:34:46.962494',2,6,'Cochin Cruise Berth, Willingdon Island','Lakshadweep & Malabar Coast','Malabar Coastal Kitchen, Spice Route Promenade, Sunset Deck Bar',3,'Traditional Cultural Amphitheatre, Sundowner Deck with Acoustic Music, Coral Glass-bottom view','Day 1: Embarkation from historic Cochin Port & Kerala Kathakali reception
