BEGIN TRANSACTION;
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(20) NOT NULL, "phone" varchar(20) NULL, "address" text NULL, "profile_picture" varchar(100) NULL, "is_approved_owner" bool NOT NULL, "whatsapp_number" varchar(30) NULL, "block_reason" varchar(255) NOT NULL, "is_verified" bool NOT NULL);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "bookings_booking" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "booking_id" varchar(32) NOT NULL UNIQUE, "booking_date" date NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "duration_hours" decimal NOT NULL, "base_price" decimal NOT NULL, "total_price" decimal NOT NULL, "number_of_people" integer unsigned NOT NULL CHECK ("number_of_people" >= 0), "special_request" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "cross_id" bigint NOT NULL REFERENCES "crosses_cross" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "booking_type" varchar(20) NOT NULL, "cabin_type" varchar(80) NOT NULL, "event_package" varchar(80) NULL, "event_type" varchar(80) NULL, "qr_code_hash" varchar(64) NULL, "adults_count" integer unsigned NOT NULL CHECK ("adults_count" >= 0), "children_count" integer unsigned NOT NULL CHECK ("children_count" >= 0), "discount_amount" decimal NOT NULL, "extras_amount" decimal NOT NULL, "invoice_number" varchar(32) NULL UNIQUE, "promo_code" varchar(30) NULL, "public_tour_id" bigint NULL REFERENCES "crosses_publictour" ("id") DEFERRABLE INITIALLY DEFERRED, "selected_extras" text NOT NULL CHECK ((JSON_VALID("selected_extras") OR "selected_extras" IS NULL)), "subtotal" decimal NOT NULL, "tax_amount" decimal NOT NULL, "tracking_status" varchar(30) NOT NULL, "net_platform_profit" decimal NOT NULL, "owner_payout_amount" decimal NOT NULL, "platform_commission_amount" decimal NOT NULL, "ticket_code" varchar(64) NOT NULL, "ticket_status" varchar(20) NOT NULL, "customer_whatsapp" varchar(30) NOT NULL, "whatsapp_reminder_error" text NOT NULL, "whatsapp_reminder_message_id" varchar(120) NOT NULL, "whatsapp_reminder_opt_in" bool NOT NULL, "whatsapp_reminder_sent" bool NOT NULL, "whatsapp_reminder_sent_at" datetime NULL, "whatsapp_reminder_status" varchar(20) NOT NULL, "cancellation_reason" text NULL, "failure_reason" varchar(255) NOT NULL, "payment_gateway_ref" varchar(120) NOT NULL, "payment_method" varchar(60) NOT NULL, "payment_status" varchar(25) NOT NULL, "payout_status" varchar(25) NOT NULL, "refund_amount" decimal NOT NULL, "refund_date" datetime NULL, "refund_reason" text NOT NULL);
